UPDATE jcfx_task a SET a.tqbz = #{tqbz,jdbcType=VARCHAR}, a.tqsj = sysdate, a.task_flag ='1', a.tqcs = tqcs+1 WHERE id=#{idkey} and task_flag<>'2' and a.tqcs<20
and a.tqbz = #{lastTqbz}
and a.tqbz is null


UPDATE jcfx_task a
			   	SET a.RESP_DATA = #{up.respData},
			        a.WCSJ = sysdate,
			        a.task_flag ='2',
			        a.SQLTEXT = #{up.sqltext}
			 	WHERE id=#{up.id}

mapper.select:
select dname
from tl_admin.sys_dict
where dtype = #{dtype} and dcode = #{dcode}

SELECT * FROM
(
SELECT A.*, ROWNUM RN
FROM (
select a.id,tqbz,tqsj,req_param as reqParam from jcfx_task  a
where task_flag in ('0','1') and  (task_flag='0' or sysdate-(tqsj+0) > #{delay}) and 20>a.tqcs
) A where 1=1

    and ROWNUM <= #{end}

)
WHERE 1=1

    and RN >= #{start}


    ORDER BY #{orderByCaluse}
